INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hamsteria!', '"Hamsteria" is a short (~1-2 hours) difficult two player co-op game where you''re each a hamster in attached wheels. You can only spin your individual wheel forwards or backwards. There is no jump button, and there is no turn action. To escape, you must work together.' FROM games WHERE igdb_id = 390684 ON CONFLICT (game_id, language_code) DO NOTHING;
