INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Vultures: Prey of Greed', 'Black Vultures is a tactical first-person shooter set in a fractured warzone where trust is scarce, resources are limited, and every mission begins with a choice. Navigate ruined infrastructure and contested zones. Intercept transmissions, track movements, and recover intel to locate your objective before rival squads close in. Engage only when necessary. Retreat when survival demands it. The deeper you push, the higher the risk, but greater the reward.' FROM games WHERE igdb_id = 357100 ON CONFLICT (game_id, language_code) DO NOTHING;
