INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Second Humanity', 'On the surface, Second Humanity seems like the ultimate school drama in a prestigious Colombian academy. As the new student in Class 02, you are surrounded by prodigies: the conciliatory Eva, the provocative Caelum, and the spectral Isoria. But beneath the marble walls of Humanity School lies a dystopia where survival depends on your ability to exploit the weaknesses of others—or perhaps, finally understand who ''They'' truly are.' FROM games WHERE igdb_id = 391869 ON CONFLICT (game_id, language_code) DO NOTHING;
