INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Táng Chuánqí: Shàng Yuáncháng Gān Xíng', 'A three-thousand-mile journey of exile, a mystery of untold evil, when strange legends are decoded into reports of social pathology, when the joy of wuxia revenge collides with the ironclad fortress of power, from bandits slaughtering villages to the powerful committing cannibalism, who is not a lamb to be slaughtered in troubled times? This game focuses on the historical backdrop of the An-Shi Rebellion during the Tang Dynasty, and every choice the player makes will mark their character''s fate.' FROM games WHERE igdb_id = 373703 ON CONFLICT (game_id, language_code) DO NOTHING;
