INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foodslingers', 'Cook, run, jump, and throw— all in the name of FoodCorp. This chaotic, physics-based spin on the classic cooking formula demands speed, strategy, and just the right amount of panic! Play with up to 4 friends and try to run the restaurant smoothly... or let it all go up in flames.' FROM games WHERE igdb_id = 344837 ON CONFLICT (game_id, language_code) DO NOTHING;
