INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scrap Daddies', 'Scrap Daddies is a slapstick co-op extraction-style looter for 1–6 players. The world has sunk beneath the waves, and survivors live on scattered platforms. Dive into deep-sea bases as a scrapper to recover power cells and gather scrap to upgrade your gear.' FROM games WHERE igdb_id = 380143 ON CONFLICT (game_id, language_code) DO NOTHING;
