INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loop the Loop: The Mansion of Gluttony', 'A closed-circle mystery visual novel where twelve people wake up inside a bizarre, impossible mansion—and a string of murders begins. Read from Remi''s point of view as you piece together the truth through his thoughts and conversations. Linear, text-focused, Japanese/English supported.' FROM games WHERE igdb_id = 387558 ON CONFLICT (game_id, language_code) DO NOTHING;
