INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grexovka Village', 'You''ve come to the village to "recharge." An hour later, you''re looking for something you''ve lost, sniffing incense in a barn, and arguing with people who smile when it suits them. Here, a glance, a pause, and what''s under the rug decide everything.' FROM games WHERE igdb_id = 386411 ON CONFLICT (game_id, language_code) DO NOTHING;
