INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baspetball', 'When the tutors leave, the house turns into a basketball court, and the ultimate showdown begins: Cats vs. Dogs. Take control of basketball-playing cats, move, pass, and shoot a yarn ball to score baskets while outsmarting dog opponents. Explore creative strategies and make that swish!' FROM games WHERE igdb_id = 346584 ON CONFLICT (game_id, language_code) DO NOTHING;
