INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drownlight', 'Drownlight is a city-building survival simulator set in a flooded world. Build and expand your city around a lighthouse, manage resources, and make moral decisions that shape the fate of the survivors. Secrets lurk in the raging waters, and if the lighthouse goes out, the city may be lost forever.' FROM games WHERE igdb_id = 338324 ON CONFLICT (game_id, language_code) DO NOTHING;
