INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starlet Voice', 'STARLET☆VOICE is a narrative talent-show survival sim set inside a 100-day televised competition. Train skills, build your persona, manage pressure, and form relationships as you navigate weekly episodes shaped by your choices. Public opinion, fan reactions, and on-air risks determine whether you rise in the rankings or fall into the elimination zone.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 380671 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
