INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallen Tear: The Ascension', 'Fallen Tear: The Ascension is an epic adventure set in a vast magical world where you’ll fight dangerous beasts, defy corrupt gods, and face many challenges, all in an attempt to bring balance back to your world.​Embark on this journey with Hira, a mysterious young boy who seeks the truth about his forgotten past. Along the way, bond with many fully-voiced characters to unlock new skills and abilities that will aid you in your battle through environments that constantly change and react to your choices - all in classic, hand-drawn animation.' FROM games WHERE igdb_id = 142304 ON CONFLICT (game_id, language_code) DO NOTHING;
