INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legacy of Ancestors', 'From the primitive age to the modern era, experience nine cycles of life. Make choices through card-based events, shaping your character’s stats, relationships, and fate. A strategy-driven life simulation wrapped in satire, tracing the absurd evolution of civilization.' FROM games WHERE igdb_id = 346589 ON CONFLICT (game_id, language_code) DO NOTHING;
