INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plague Alchemist', 'Plague Alchemist is a singleplayer adventure RPG with a deep focus on alchemy. Explore a world where the mundane intertwines with the magical and the corrupt. Harvest and loot your way to uncover the truth behind the world''s mysterious decay. Perhaps there is more to it than meets the eye.' FROM games WHERE igdb_id = 368291 ON CONFLICT (game_id, language_code) DO NOTHING;
