INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeremy, No!', 'Jeremy, No! Is a spot the difference horror game where you are babysitting a poltergeist named Jeremy. Jeremy isn’t allowed to move stuff around or invite any “friends”, so carefully look at the rooms and call him out if anything has changed. Don’t let Jeremy get away with too many shenanigans...' FROM games WHERE igdb_id = 385986 ON CONFLICT (game_id, language_code) DO NOTHING;
