INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just A Shadow Game', 'Hear me, pitiful mortals, for I shall reveal to you the path to true power - a demonic fusion of deckbuilding, ritual duels, and roguelite! I speak of a realm shrouded in darkness, where only the most wicked may thrive. Behold my masterpiece, "Just A Shadow Game".' FROM games WHERE igdb_id = 326918 ON CONFLICT (game_id, language_code) DO NOTHING;
