INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chipmatic', 'Chipmatic is a factory building game where you control a mining robot on a mission to reach Earth’s core. Explore deep underground, research new tech and create the best (and only) factory on Earth! Can you discover what mysteries lie beneath the surface in this ruined planet some used to call home?' FROM games WHERE igdb_id = 355037 ON CONFLICT (game_id, language_code) DO NOTHING;
