INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Six Mobile', 'From the acclaimed Rainbow Six franchise, Rainbow Six Mobile is a competitive, multiplayer first-person shooter experience on your phone. Compete in Rainbow Six''s classic Attack vs. Defense game modes. Play as an Attacker or Defender in fast-paced 5v5 matches and face intense close-quarter combat while making timely tactical decisions. Choose from a roster of highly trained Operators, each with their own unique abilities and gadgets. Experience this ultimate tactical shooter game, designed exclusively for mobile.' FROM games WHERE igdb_id = 200333 ON CONFLICT (game_id, language_code) DO NOTHING;
