INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paracesium', 'PARACESIUM is a body horror time management game where you collect, analyze, dismember and reassemble body parts in order to create a pure cadaver for your experimentation. Every action takes time, so make your next decision carefully. Manage time, bodies and monsters and stay alive. Who is Delilah?' FROM games WHERE igdb_id = 386160 ON CONFLICT (game_id, language_code) DO NOTHING;
