INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puppe Yerde', 'Puppe Yerde is a calm, casual game where you spend seven days with a small puppy in a quiet garden. There are no battles or game overs. You simply take photos, earn points based on the puppy''s behavior, and collect unlockable hats. Designed as a gentle, relaxing experience for players of all ages.' FROM games WHERE igdb_id = 392753 ON CONFLICT (game_id, language_code) DO NOTHING;
