INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Kepler: Delivery Included!', 'Project Kepler: Delivery Included! is a roguelike base-defense game where players control a lone cyborg stranded on a hostile planet. The objective is to survive waves of evolving alien creatures while managing resources, constructing automated defenses, and deploying drones for combat and support. Key features include procedurally generated runs, upgradeable drones and turrets, automation systems, daily randomized upgrades, and an ultimate fail-safe: an orbital strike to eradicate the planet.' FROM games WHERE igdb_id = 363050 ON CONFLICT (game_id, language_code) DO NOTHING;
