INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless TD', 'Endless TD is a multiplayer tower defense game focused on deep buildcraft, co-op survival, and competitive PvP. Team up with friends to survive endlessly scaling waves, experiment with elemental synergies and tower merges, or face off by sending enemies to overwhelm your opponents. Every run plays differently, rewarding strategy, creativity, and smart decisions.' FROM games WHERE igdb_id = 388515 ON CONFLICT (game_id, language_code) DO NOTHING;
