INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Subject: Protocol Zero', 'Turn on your camera. The Kessler Foundation is paying for your pain. The game uses your webcam and microphone, turning the room into a lab. Complete four stages: from the blink ban to the "Green Light, Red Light" game. Money or sanity? Be the first to complete Protocol Zero. If you dare.' FROM games WHERE igdb_id = 389852 ON CONFLICT (game_id, language_code) DO NOTHING;
