INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Have One Shot', 'You Have One Shot is a game in which you will need to select the moment when exactly you need to shoot, since you only have one shell and you will need to use it to destroy all the enemies on the level. If you shoot and don''t hit all the enemies, you will lose. If you destroy all enemies with one shell, you will move to the next level.' FROM games WHERE igdb_id = 390120 ON CONFLICT (game_id, language_code) DO NOTHING;
