INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parallel Hearts', 'Parallel Hearts is a romantic, choice-driven visual novel about a connection that starts where most stories end—after you close your eyes. Each night, Nora meets a boy by a quiet lakeside; each morning, she remembers everything…and he remembers nothing. As the dreams grow shorter, clues from the dream world begin pointing to places in the real one, and Nora must decide whether this is fate—or a feeling she’s brave enough to follow.' FROM games WHERE igdb_id = 390870 ON CONFLICT (game_id, language_code) DO NOTHING;
