INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mafia Business Simulator', 'Step into the thrilling world of Mafia Business Simulator, a game where crime isn’t chaos — it’s a high-stakes, calculated business. Experience the excitement of running your own criminal empire in modern London, where every decision counts, every move shapes your influence, and every rival is waiting for a mistake. Stylish, immersive, and full of strategic depth, this is more than a game — it’s your chance to dominate the city from the shadows.' FROM games WHERE igdb_id = 394480 ON CONFLICT (game_id, language_code) DO NOTHING;
