INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corpse Party II: Darkness Distortion', 'Corpse Party II: Darkness Distortion follows three high school friends; Haruka Nanami, Nemu Takanashi, and Maria Hitsugi, as they explore the Amare Est Vivere Hospital, testing a local urban legend as the streamer Nemu seeks to boost her subscriber count. Unfortunately for the three girls, the legend of “Ayame’s Mercy” is true, and they trigger a decades-old curse that sends them into a dark realm. Together they must avoid the vengeful spirit of Ayame Kirishima and other horrors from the hospital’s dark past as they search for a way to dispel Ayame’s curse once and for all.' FROM games WHERE igdb_id = 261147 ON CONFLICT (game_id, language_code) DO NOTHING;
